-- Mock data: customer CBZ, its subsidiaries (banks + bank_customers), users and their roles.
--
-- MOCK DATA ONLY — for local/dev/test environments, never production.
--   * Emails use the reserved ".example" domain so nothing can reach a real mailbox.
--   * Every user's password is "Mavhu@2026" (bcrypt, cost 10).
--
-- Idempotent: rows are matched on their natural keys (emails, role names, bank/customer pairs),
-- so re-running inserts nothing new. IDs are generated by the database, never hard-coded.
-- Run after the DDL scripts in db/ddl:
--   psql -h <host> -U mavhu_ingestion_service -d mavhu_db -v ON_ERROR_STOP=1 -f src/main/resources/db/mock/cbz_mock_data.sql

BEGIN;

-- Roles (already created by migrations in most environments) -----------------------------------
INSERT INTO mavhu.roles (name) VALUES ('MANAGER'), ('ESG_TEAM'), ('AUDITOR')
ON CONFLICT (name) DO NOTHING;

-- Customer ------------------------------------------------------------------------------------
-- hectares is mandatory (> 0) on customers; 1127 ha is the total distinct site area monitored in the
-- Satellite & Geospatial sample (10_Satellite_Geospatial.xlsx).
INSERT INTO mavhu.customers (name, hectares, country, email, phone_number, identifier)
VALUES ('CBZ', 1127, 'Zimbabwe', 'esg@cbz.example', NULL, 'BANK')
ON CONFLICT (email) DO NOTHING;

-- Subsidiaries as banks ---------------------------------------------------------------------
-- banks.identifier holds the entity code used in the ESG files' Subsidiary columns
-- (see 02_Entity_Reference.xlsx), so ingested rows can be joined back to a subsidiary.
INSERT INTO mavhu.banks (name, country, email, phone_number, identifier) VALUES
    -- Flagship commercial bank: retail, corporate and mortgage banking
    ('CBZ Bank Limited',               'Zimbabwe', 'bank@cbz.example',       NULL, 'CBZBANK'),
    -- Long-term life insurance and assurance
    ('CBZ Life',                       'Zimbabwe', 'life@cbz.example',       NULL, 'CBZLIFE'),
    -- Short-term and general insurance
    ('CBZ Insurance',                  'Zimbabwe', 'insurance@cbz.example',  NULL, 'CBZINS'),
    -- Asset management and investment portfolios
    ('Datvest (CBZ Asset Management)', 'Zimbabwe', 'datvest@cbz.example',    NULL, 'DATVEST'),
    -- Property investment, development and management
    ('CBZ Properties',                 'Zimbabwe', 'properties@cbz.example', NULL, 'CBZPROP'),
    -- Microfinance and SME finance
    ('CBZ Red Sphere Finance',         'Zimbabwe', 'redsphere@cbz.example',  NULL, 'CBZRED'),
    -- Agricultural financing and support
    ('CBZ Agro-Yield',                 'Zimbabwe', 'agroyield@cbz.example',  NULL, 'CBZAGRO'),
    -- Insurance brokerage and risk management consultancy
    ('CBZ Risk Advisory Services',     'Zimbabwe', 'riskadvisory@cbz.example', NULL, 'CBZRISK'),
    -- Corporate finance, securities trading and advisory
    ('CBZ Capital',                    'Zimbabwe', 'capital@cbz.example',    NULL, 'CBZCAP')
ON CONFLICT (email) DO NOTHING;

-- Each subsidiary belongs to customer CBZ; the reference number is the subsidiary's entity code.
INSERT INTO mavhu.bank_customers (bank_id, customer_id, customer_reference_number)
SELECT b.id, c.id, b.identifier
FROM mavhu.banks b
CROSS JOIN mavhu.customers c
WHERE c.email = 'esg@cbz.example'
  AND b.email IN ('bank@cbz.example', 'life@cbz.example', 'insurance@cbz.example', 'datvest@cbz.example',
                  'properties@cbz.example', 'redsphere@cbz.example', 'agroyield@cbz.example',
                  'riskadvisory@cbz.example', 'capital@cbz.example')
ON CONFLICT (bank_id, customer_id) DO NOTHING;

-- Users of customer CBZ (Zimbabwean names) ------------------------------------------------------
INSERT INTO mavhu.users (name, customer_id, estate_id, email, password)
SELECT u.name, c.id, NULL, u.email, '$2y$10$arETCx.cMbJE.qsgow27Vu3W..SdsrIF8kk.AHu4dS6EzprKl6/xm'
FROM (VALUES
    ('Tendai Moyo',       'tendai.moyo@cbz.example'),
    ('Nomsa Ndlovu',      'nomsa.ndlovu@cbz.example'),
    ('Tatenda Shumba',    'tatenda.shumba@cbz.example'),
    ('Chiedza Mpofu',     'chiedza.mpofu@cbz.example'),
    ('Farai Sibanda',     'farai.sibanda@cbz.example'),
    ('Rudo Marufu',       'rudo.marufu@cbz.example'),
    ('Thandiwe Ncube',    'thandiwe.ncube@cbz.example'),
    ('Kudakwashe Gumbo',  'kudakwashe.gumbo@cbz.example'),
    ('Tapiwa Dube',       'tapiwa.dube@cbz.example')
) AS u (name, email)
CROSS JOIN mavhu.customers c
WHERE c.email = 'esg@cbz.example'
ON CONFLICT (email) DO NOTHING;

-- Roles: managers approve/reject files, the ESG team uploads them, the auditor reviews.
INSERT INTO mavhu.user_roles (user_id, role_id, audit_trail)
SELECT u.id, r.id, 'Seeded by db/mock/cbz_mock_data.sql'
FROM (VALUES
    ('tendai.moyo@cbz.example',      'MANAGER'),
    ('nomsa.ndlovu@cbz.example',     'MANAGER'),
    ('tatenda.shumba@cbz.example',   'ESG_TEAM'),
    ('chiedza.mpofu@cbz.example',    'ESG_TEAM'),
    ('farai.sibanda@cbz.example',    'ESG_TEAM'),
    ('rudo.marufu@cbz.example',      'ESG_TEAM'),
    ('thandiwe.ncube@cbz.example',   'ESG_TEAM'),
    ('kudakwashe.gumbo@cbz.example', 'ESG_TEAM'),
    ('tapiwa.dube@cbz.example',      'AUDITOR')
) AS ur (email, role_name)
JOIN mavhu.users u ON u.email = ur.email
JOIN mavhu.roles r ON r.name = ur.role_name
WHERE NOT EXISTS (SELECT 1 FROM mavhu.user_roles x WHERE x.user_id = u.id AND x.role_id = r.id);

COMMIT;

-- Generated IDs (use these as customerId / userId when calling the API):
SELECT c.id AS customer_id, c.name AS customer, u.id AS user_id, u.name AS user_name, u.email, r.name AS role
FROM mavhu.customers c
JOIN mavhu.users u ON u.customer_id = c.id
LEFT JOIN mavhu.user_roles ur ON ur.user_id = u.id
LEFT JOIN mavhu.roles r ON r.id = ur.role_id
WHERE c.email = 'esg@cbz.example'
ORDER BY u.id;
